import type { CricketProvider, DateRange } from '../types.js';
import type { Match, MatchState, Scorecard, Commentary, MatchFormat, MatchStatus, TeamScoreSummary } from '../../types/models.js';
import { CircuitBreaker } from '../circuit-breaker.js';
import { QuotaGuard } from '../quota-guard.js';
import { getTeamCode } from '../../teams.js';
import {
  CricketDataCurrentMatchesResponseSchema,
  CricketDataMatchesResponseSchema,
  CricketDataMatchInfoResponseSchema,
  CricketDataScorecardResponseSchema,
  CricketDataSeriesListResponseSchema,
  CricketDataSeriesInfoResponseSchema,
  CricketDataMatchItem,
} from './schemas.js';

// Fallback fixture imports for offline/no-key graceful resilience
import currentMatchesFixture from './__fixtures__/currentMatches.json' with { type: 'json' };
import matchesFixture from './__fixtures__/matches.json' with { type: 'json' };
import matchInfoFixture from './__fixtures__/match_info.json' with { type: 'json' };
import matchScorecardFixture from './__fixtures__/match_scorecard.json' with { type: 'json' };

export interface CricketDataOrgOptions {
  apiKey?: string;
  apiKeys?: string[];
  baseUrl?: string;
  dailyBudget?: number;
  useOfflineFixturesOnly?: boolean;
  onCallLogged?: (info: { endpoint: string; statusCode: number; durationMs: number; success: boolean }) => Promise<void> | void;
}

/**
 * CricketData.org (api.cricapi.com) provider adapter with Dynamic Multi-Key Failover Pool.
 * Automatically rotates to the next API key when daily hit limit or rate limit is reached.
 */
export class CricketDataOrgProvider implements CricketProvider {
  public readonly name = 'cricketdata';
  private readonly apiKeys: string[];
  private currentKeyIndex = 0;
  private readonly baseUrl: string;
  private readonly circuitBreaker: CircuitBreaker;
  private readonly quotaGuard: QuotaGuard;
  private readonly onCallLogged?: CricketDataOrgOptions['onCallLogged'];
  private readonly useOfflineFixturesOnly: boolean;

  private static exhaustedKeys = new Set<string>();
  private static isBlockedUntilTomorrow = false;
  private static blockedDate = '';
  private static failedEndpoints = new Set<string>();

  constructor(options: CricketDataOrgOptions = {}) {
    this.useOfflineFixturesOnly = !!options.useOfflineFixturesOnly;
    const rawKeys: string[] = [];
    if (!this.useOfflineFixturesOnly) {
      if (options.apiKeys) rawKeys.push(...options.apiKeys);
      if (options.apiKey) rawKeys.push(options.apiKey);
      if (process.env.CRICKET_API_KEYS) rawKeys.push(...process.env.CRICKET_API_KEYS.split(','));
      if (process.env.CRICKET_API_KEY) rawKeys.push(process.env.CRICKET_API_KEY);
      if (process.env.CRICKET_DATA_API_KEY) rawKeys.push(process.env.CRICKET_DATA_API_KEY);
    }

    this.apiKeys = Array.from(
      new Set(rawKeys.map((k) => k.trim()).filter((k) => k && k !== 'placeholder' && !k.includes('test-key')))
    );

    this.baseUrl = options.baseUrl || 'https://api.cricapi.com/v1';
    this.circuitBreaker = new CircuitBreaker({
      failureThreshold: 3,
      recoveryTimeMs: 60_000,
      timeoutMs: 8_000,
    });

    const keyCount = Math.max(1, this.apiKeys.length);
    const totalBudget = (options.dailyBudget ?? 100) * keyCount;

    this.quotaGuard = new QuotaGuard({
      providerName: 'CricketDataOrg',
      dailyBudget: totalBudget,
      maxCallsPerMinute: 20 * keyCount,
    });
    this.onCallLogged = options.onCallLogged;
  }

  private getActiveKey(): string {
    while (this.currentKeyIndex < this.apiKeys.length) {
      const key = this.apiKeys[this.currentKeyIndex];
      if (!CricketDataOrgProvider.exhaustedKeys.has(key)) {
        return key;
      }
      this.currentKeyIndex++;
    }
    return '';
  }

  private markKeyExhausted(key: string, reason: string): string | null {
    CricketDataOrgProvider.exhaustedKeys.add(key);
    const redacted = key.length > 4 ? `...${key.slice(-4)}` : '****';
    console.warn(`🔄 [CricketDataOrgProvider] API key ${redacted} reached quota limit (${reason}).`);

    this.currentKeyIndex++;
    const nextKey = this.getActiveKey();
    if (nextKey) {
      const nextRedacted = nextKey.length > 4 ? `...${nextKey.slice(-4)}` : '****';
      console.log(`✨ [CricketDataOrgProvider] Automatically switched to next API key in pool (${nextRedacted}).`);
      this.circuitBreaker.reset();
      return nextKey;
    } else {
      console.error(
        `🚨 [CricketDataOrgProvider] All ${this.apiKeys.length} API keys exhausted for today. Locking provider.`
      );
      CricketDataOrgProvider.isBlockedUntilTomorrow = true;
      CricketDataOrgProvider.blockedDate = new Date().toISOString().slice(0, 10);
      return null;
    }
  }

  private async fetchApi<T>(endpoint: string, params: Record<string, string> = {}): Promise<T> {
    const today = new Date().toISOString().slice(0, 10);
    const paramKey = `${endpoint}:${JSON.stringify(params)}`;

    // 1. If provider was blocked today due to hit limits, immediately return fixture
    if (CricketDataOrgProvider.isBlockedUntilTomorrow && CricketDataOrgProvider.blockedDate === today) {
      console.warn(`[CricketDataOrgProvider] Daily quota exceeded on provider. Serving cached fixture for ${endpoint}.`);
      return this.getFixtureData<T>(endpoint, params);
    }

    // 2. If this specific item previously failed (e.g. scorecard not found), return fixture without retrying
    if (CricketDataOrgProvider.failedEndpoints.has(paramKey)) {
      return this.getFixtureData<T>(endpoint, params);
    }

    // 3. Get active key from pool
    const activeKey = this.getActiveKey();
    if (!activeKey) {
      console.warn(`[CricketDataOrgProvider] No active CRICKET_API_KEY available in pool. Serving verified fixture for ${endpoint}.`);
      return this.getFixtureData<T>(endpoint, params);
    }

    // 4. Check daily quota and rate limits before attempting live network call
    try {
      this.quotaGuard.checkQuota();
    } catch (quotaErr: any) {
      console.warn(`[CricketDataOrgProvider] Quota guard stopped call: ${quotaErr.message}. Serving fixture.`);
      return this.getFixtureData<T>(endpoint, params);
    }

    const startTime = Date.now();
    const url = new URL(`${this.baseUrl}/${endpoint}`);
    url.searchParams.set('apikey', activeKey);
    for (const [key, val] of Object.entries(params)) {
      url.searchParams.set(key, val);
    }

    try {
      const result = await this.circuitBreaker.execute(async () => {
        this.quotaGuard.recordCall();
        const res = await fetch(url.toString(), {
          headers: { Accept: 'application/json' },
        });

        const durationMs = Date.now() - startTime;
        const statusCode = res.status;

        if (statusCode === 429) {
          this.markKeyExhausted(activeKey, 'HTTP 429 Rate Limit');
          throw new Error('API key rate limited');
        }

        if (!res.ok) {
          if (this.onCallLogged) {
            await this.onCallLogged({ endpoint, statusCode, durationMs, success: false });
          }
          throw new Error(`CricketData API error [${statusCode}]: ${res.statusText}`);
        }

        const json = await res.json();
        const isSuccess = json.status === 'success';

        if (this.onCallLogged) {
          await this.onCallLogged({ endpoint, statusCode, durationMs, success: isSuccess });
        }

        if (!isSuccess) {
          const reason = String(json.reason || json.message || 'Unknown error');

          // Check if CricAPI hit limit was reached or blocked for this key
          if (
            reason.toLowerCase().includes('exceeded limit') ||
            reason.toLowerCase().includes('blocking') ||
            reason.toLowerCase().includes('hit limit')
          ) {
            const hasNext = this.markKeyExhausted(activeKey, reason);
            if (hasNext) {
              // Retry immediately with next key
              return null;
            }
          }

          // Negative cache 404 / not found scorecards so we never re-request them
          if (reason.toLowerCase().includes('not found') || reason.toLowerCase().includes('err: scorecard')) {
            CricketDataOrgProvider.failedEndpoints.add(paramKey);
          }

          throw new Error(`CricketData API failure: ${reason}`);
        }

        return json as T;
      });

      if (result === null && this.getActiveKey()) {
        // Rotated key, retry call
        return this.fetchApi<T>(endpoint, params);
      }

      return result as T;
    } catch (err: any) {
      if (this.getActiveKey() && (err.message.includes('rate limited') || err.message.includes('quota limit'))) {
        return this.fetchApi<T>(endpoint, params);
      }
      console.error(`[CricketDataOrgProvider] Live call to ${endpoint} failed: ${err.message}. Using cached fixture.`);
      return this.getFixtureData<T>(endpoint, params);
    }
  }

  private getFixtureData<T>(endpoint: string, params: Record<string, string>): T {
    switch (endpoint) {
      case 'currentMatches':
        return currentMatchesFixture as unknown as T;
      case 'matches':
        return matchesFixture as unknown as T;
      case 'match_info':
        return matchInfoFixture as unknown as T;
      case 'match_scorecard':
        return matchScorecardFixture as unknown as T;
      default:
        return currentMatchesFixture as unknown as T;
    }
  }

  public getQuotaStats() {
    return this.quotaGuard.getStats();
  }

  /**
   * Fetches all current matches (ONE call returns live, today's upcoming, and today's finished).
   */
  public async getCurrentMatches(): Promise<Match[]> {
    const raw = await this.fetchApi<any>('currentMatches');
    const parsed = CricketDataCurrentMatchesResponseSchema.safeParse(raw);
    const dataList = parsed.success ? parsed.data.data : raw.data || [];
    return dataList.map((m: CricketDataMatchItem) => this.normalizeMatch(m));
  }

  /**
   * Returns only live matches from currentMatches.
   */
  public async getLiveMatches(): Promise<Match[]> {
    const matches = await this.getCurrentMatches();
    return matches.filter((m) => m.status === 'live');
  }

  /**
   * Upcoming fixtures list.
   */
  public async getFixtures(range?: DateRange): Promise<Match[]> {
    const raw = await this.fetchApi<any>('matches');
    const parsed = CricketDataMatchesResponseSchema.safeParse(raw);
    const dataList = parsed.success ? parsed.data.data : raw.data || [];
    return dataList.map((m: CricketDataMatchItem) => this.normalizeMatch(m));
  }

  /**
   * Match info single item.
   */
  public async getMatchInfo(matchId: string): Promise<Match> {
    const raw = await this.fetchApi<any>('match_info', { id: matchId });
    const parsed = CricketDataMatchInfoResponseSchema.safeParse(raw);
    const item = parsed.success ? parsed.data.data : raw.data || raw;
    return this.normalizeMatch(item);
  }

  /**
   * Full match scorecard.
   */
  public async getScorecard(matchId: string): Promise<Scorecard> {
    const raw = await this.fetchApi<any>('match_scorecard', { id: matchId });
    const parsed = CricketDataScorecardResponseSchema.safeParse(raw);
    const matchData = parsed.success ? parsed.data.data : raw.data || raw;
    const normalizedMatch = this.normalizeMatch(matchData);

    return {
      match: normalizedMatch,
      innings: this.normalizeInningsList(matchData.scorecard || [], normalizedMatch),
    };
  }

  /**
   * Match snapshot for realtime state SSE stream.
   */
  public async getMatchSnapshot(matchId: string): Promise<MatchState> {
    const scorecardData = await this.getScorecard(matchId);
    return this.normalizeMatchState(scorecardData);
  }

  /**
   * Commentary. Free tier provides basic over summaries.
   */
  public async getCommentary(matchId: string, cursor?: string): Promise<Commentary[]> {
    return [];
  }

  /**
   * Series list.
   */
  public async getSeriesList(): Promise<any[]> {
    const raw = await this.fetchApi<any>('series');
    const parsed = CricketDataSeriesListResponseSchema.safeParse(raw);
    return parsed.success ? parsed.data.data : raw.data || [];
  }

  /**
   * Series info with match list.
   */
  public async getSeriesInfo(seriesId: string): Promise<any> {
    const raw = await this.fetchApi<any>('series_info', { id: seriesId });
    const parsed = CricketDataSeriesInfoResponseSchema.safeParse(raw);
    return parsed.success ? parsed.data.data : raw.data || raw;
  }

  /**
   * Robust status derivation.
   * Derives: 'upcoming' | 'live' | 'completed' | 'abandoned'
   */
  public deriveMatchStatus(raw: CricketDataMatchItem): MatchStatus {
    const statusTextLower = (raw.status || '').toLowerCase();

    // Check abandoned / no result first
    if (
      statusTextLower.includes('abandoned') ||
      statusTextLower.includes('no result') ||
      statusTextLower.includes('cancelled')
    ) {
      return 'abandoned';
    }

    // Direct boolean flags from API if present
    if (typeof raw.matchEnded === 'boolean' && raw.matchEnded) {
      return 'completed';
    }

    if (typeof raw.matchStarted === 'boolean') {
      if (raw.matchStarted && !raw.matchEnded) {
        return 'live';
      }
      if (!raw.matchStarted) {
        return 'upcoming';
      }
    }

    // Infer from status text
    if (
      statusTextLower.includes('won by') ||
      statusTextLower.includes('win by') ||
      statusTextLower.includes('drawn') ||
      statusTextLower.includes('tied') ||
      statusTextLower.includes('conceded') ||
      Boolean(raw.matchWinner)
    ) {
      return 'completed';
    }

    if (
      statusTextLower.includes('need') ||
      statusTextLower.includes('trail by') ||
      statusTextLower.includes('lead by') ||
      statusTextLower.includes('opt to') ||
      statusTextLower.includes('chose to') ||
      statusTextLower.includes('day ') ||
      statusTextLower.includes('tea break') ||
      statusTextLower.includes('lunch') ||
      statusTextLower.includes('stumps') ||
      statusTextLower.includes('innings break')
    ) {
      return 'live';
    }

    if (
      statusTextLower.includes('starts at') ||
      statusTextLower.includes('match starts') ||
      statusTextLower.includes('scheduled')
    ) {
      return 'upcoming';
    }

    // Fallback: If score array has scores, assume live
    if (Array.isArray(raw.score) && raw.score.length > 0) {
      return 'live';
    }

    return 'upcoming';
  }

  /**
   * Parses format e.g. "t20" -> "T20", "odi" -> "ODI", "test" -> "TEST"
   */
  private deriveMatchFormat(rawType?: string): MatchFormat {
    const t = (rawType || '').toLowerCase();
    if (t.includes('t20')) return 'T20';
    if (t.includes('odi')) return 'ODI';
    if (t.includes('test')) return 'TEST';
    if (t.includes('100') || t.includes('hundred') || t.includes('t10')) return '100BALL';
    return 'T20';
  }

  /**
   * Parses match stage/number label e.g. "4th T20I", "Final", "Match 14", "1st ODI"
   */
  private extractMatchNumber(name: string): string | undefined {
    if (!name) return undefined;
    const matchMatch = name.match(/(\d+(?:st|nd|rd|th)?\s+(?:Match|T20I?|ODI|Test)|Match\s+\d+|Final|Semi-Final)/i);
    if (matchMatch) return matchMatch[0].trim();
    const parts = name.split(',');
    return parts.length > 1 ? parts[1].trim() : undefined;
  }

  /**
   * Normalizes innings scores into team summaries.
   */
  private computeTeamScoreSummaries(
    scores: Array<{ r: number; w: number; o: number; inning: string }>,
    teamAName: string,
    teamBName: string
  ): { teamAScore?: TeamScoreSummary; teamBScore?: TeamScoreSummary } {
    if (!scores || scores.length === 0) return {};

    const teamAScores: Array<{ r: number; w: number; o: number; inning: string }> = [];
    const teamBScores: Array<{ r: number; w: number; o: number; inning: string }> = [];

    const normA = teamAName.toLowerCase();
    const normB = teamBName.toLowerCase();

    for (const s of scores) {
      const innLower = s.inning.toLowerCase();
      if (innLower.includes(normA) || (teamAScores.length === 0 && !innLower.includes(normB))) {
        teamAScores.push(s);
      } else {
        teamBScores.push(s);
      }
    }

    const formatSummary = (
      teamScores: Array<{ r: number; w: number; o: number; inning: string }>
    ): TeamScoreSummary | undefined => {
      if (teamScores.length === 0) return undefined;
      const latest = teamScores[teamScores.length - 1];

      // Multi-innings (e.g. Test match: "382 & 210/4 (54.0)")
      if (teamScores.length > 1) {
        const parts = teamScores.map((ts, idx) => {
          const isLast = idx === teamScores.length - 1;
          const scoreStr = ts.w >= 10 ? `${ts.r}` : `${ts.r}/${ts.w}`;
          return isLast ? `${scoreStr} (${ts.o})` : scoreStr;
        });
        return {
          runs: latest.r,
          wickets: latest.w,
          overs: latest.o,
          display: parts.join(' & '),
        };
      }

      // Single inning (e.g. "184/4 (20.0)")
      const scoreStr = latest.w >= 10 ? `${latest.r}` : `${latest.r}/${latest.w}`;
      return {
        runs: latest.r,
        wickets: latest.w,
        overs: latest.o,
        display: `${scoreStr} (${latest.o})`,
      };
    };

    return {
      teamAScore: formatSummary(teamAScores),
      teamBScore: formatSummary(teamBScores),
    };
  }

  /**
   * Normalizes a raw CricketData match into LiveCricket Match model.
   */
  public normalizeMatch(raw: CricketDataMatchItem): Match {
    let rawTeamAName = raw.teamInfo?.[0]?.name || raw.teams?.[0] || 'Team A';
    let rawTeamBName = raw.teamInfo?.[1]?.name || raw.teams?.[1] || 'Team B';

    // Handle CricAPI comma-split quirk (e.g. "Hong Kong, China vs Singapore")
    if ((!raw.teams || raw.teams.length < 2) && raw.name.includes(' vs ')) {
      const vsIndex = raw.name.indexOf(' vs ');
      const beforeVs = raw.name.substring(0, vsIndex).trim();
      const afterVs = raw.name.substring(vsIndex + 4).trim();
      const afterVsTeam = afterVs.split(',')[0].trim();
      rawTeamAName = beforeVs;
      rawTeamBName = afterVsTeam;
    }

    const teamACode = getTeamCode(rawTeamAName, raw.teamInfo?.[0]?.shortname);
    const teamBCode = getTeamCode(rawTeamBName, raw.teamInfo?.[1]?.shortname);

    const scores = raw.score || [];
    const { teamAScore, teamBScore } = this.computeTeamScoreSummaries(scores, rawTeamAName, rawTeamBName);
    const status = this.deriveMatchStatus(raw);
    const matchNumber = this.extractMatchNumber(raw.name);

    // Extract series name from name parts if compound (e.g. "..., ICC Mens T20 World Cup...")
    let seriesName = raw.series_id || 'Cricket Tournament';
    const nameParts = raw.name.split(',').map((p) => p.trim());
    if (nameParts.length >= 3) {
      seriesName = nameParts.slice(2).join(', ');
    } else if (nameParts.length === 2) {
      seriesName = nameParts[0];
    } else {
      seriesName = raw.name;
    }

    return {
      id: raw.id || 'unknown',
      slug: (raw.name || `${teamACode}-vs-${teamBCode}`).toLowerCase().replace(/[^a-z0-9]+/g, '-'),
      title: `${rawTeamAName} vs ${rawTeamBName}`,
      seriesId: raw.series_id || 'series-default',
      seriesName,
      format: this.deriveMatchFormat(raw.matchType),
      status,
      statusText: raw.status || 'Scheduled',
      venue: raw.venue || 'Stadium',
      city: raw.venue ? raw.venue.split(',')[1]?.trim() || raw.venue.split(',')[0]?.trim() || 'City' : 'City',
      startTime: raw.dateTimeGMT || (raw.date ? `${raw.date}T00:00:00Z` : new Date().toISOString()),
      matchNumber,
      teamA: {
        id: teamACode.toLowerCase(),
        name: rawTeamAName,
        shortName: teamACode,
        code: teamACode,
        logoUrl: raw.teamInfo?.[0]?.img,
      },
      teamB: {
        id: teamBCode.toLowerCase(),
        name: rawTeamBName,
        shortName: teamBCode,
        code: teamBCode,
        logoUrl: raw.teamInfo?.[1]?.img,
      },
      teamAScore,
      teamBScore,
      scores,
      toss: raw.tossWinner
        ? {
            winnerId: getTeamCode(raw.tossWinner).toLowerCase(),
            decision: (raw.tossChoice as any) || 'bat',
            text: `${raw.tossWinner} chose to ${raw.tossChoice || 'bat'}`,
          }
        : undefined,
      winnerId: raw.matchWinner ? getTeamCode(raw.matchWinner).toLowerCase() : undefined,
      resultText: raw.status,
      currentInningsNumber: scores.length > 0 ? scores.length : 1,
      hasSquad: raw.hasSquad,
      fantasyEnabled: raw.fantasyEnabled,
      bbbEnabled: raw.bbbEnabled,
    };
  }

  /**
   * Normalizes innings array from match_scorecard.
   */
  private normalizeInningsList(rawScorecards: any[], match: Match): any[] {
    return rawScorecards.map((sc, index) => {
      const isTeamA = sc.inning?.toLowerCase().includes(match.teamA.name.toLowerCase());
      const battingTeamId = isTeamA ? match.teamA.id : match.teamB.id;
      const bowlingTeamId = isTeamA ? match.teamB.id : match.teamA.id;

      const runs = sc.totals?.R ?? 0;
      const wickets = sc.totals?.W ?? 0;
      const overs = sc.totals?.O ?? 0;
      const runRate = sc.totals?.RR ?? (overs > 0 ? Number((runs / overs).toFixed(2)) : 0);

      const batters = (sc.batting || []).map((b: any) => ({
        id: b.batsman?.id || b.batsman?.name?.toLowerCase().replace(/\s+/g, '-') || 'p',
        name: b.batsman?.name || 'Batsman',
        runs: b.r ?? 0,
        balls: b.b ?? 0,
        fours: b['4s'] ?? 0,
        sixes: b['6s'] ?? 0,
        strikeRate: b.sr ?? 0,
        isOut: b.dismissal !== 'not out',
        dismissal: b['dismissal-text']
          ? {
              type: 'caught' as any,
              text: b['dismissal-text'],
            }
          : undefined,
      }));

      const bowlers = (sc.bowling || []).map((bw: any) => ({
        id: bw.bowler?.id || bw.bowler?.name?.toLowerCase().replace(/\s+/g, '-') || 'bw',
        name: bw.bowler?.name || 'Bowler',
        overs: bw.o ?? 0,
        maidens: bw.m ?? 0,
        runs: bw.r ?? 0,
        wickets: bw.w ?? 0,
        economy: bw.eco ?? 0,
        wides: 0,
        noBalls: 0,
        dots: 0,
      }));

      return {
        id: `inn-${index + 1}`,
        matchId: match.id,
        inningsNumber: index + 1,
        battingTeamId,
        bowlingTeamId,
        runs,
        wickets,
        overs,
        balls: Math.floor(overs) * 6 + Math.round((overs % 1) * 10),
        runRate,
        extras: {
          wides: sc.extras?.w ?? 0,
          noBalls: sc.extras?.nb ?? 0,
          byes: sc.extras?.b ?? 0,
          legByes: sc.extras?.lb ?? 0,
          penalty: sc.extras?.p ?? 0,
          total: sc.extras?.r ?? 0,
        },
        batters,
        bowlers,
        fallOfWickets: [],
        isCompleted: wickets >= 10 || sc.totals?.O >= 20,
      };
    });
  }

  /**
   * Builds MatchState from scorecard.
   */
  private normalizeMatchState(scorecardData: Scorecard): MatchState {
    const { match, innings } = scorecardData;
    const currentInnings = innings[innings.length - 1] || {
      id: 'inn-1',
      matchId: match.id,
      inningsNumber: 1,
      battingTeamId: match.teamA.id,
      bowlingTeamId: match.teamB.id,
      runs: match.teamAScore?.runs ?? 0,
      wickets: match.teamAScore?.wickets ?? 0,
      overs: match.teamAScore?.overs ?? 0,
      balls: 0,
      runRate: 0,
      extras: { wides: 0, noBalls: 0, byes: 0, legByes: 0, penalty: 0, total: 0 },
      batters: [],
      bowlers: [],
      fallOfWickets: [],
      isCompleted: false,
    };

    const notOutBatters = currentInnings.batters.filter((b) => !b.isOut);
    const b1 = notOutBatters[0] || {
      id: 'b1',
      name: 'Striker',
      runs: 0,
      balls: 0,
      fours: 0,
      sixes: 0,
      strikeRate: 0,
      isOut: false,
    };
    const b2 = notOutBatters[1] || {
      id: 'b2',
      name: 'Non-striker',
      runs: 0,
      balls: 0,
      fours: 0,
      sixes: 0,
      strikeRate: 0,
      isOut: false,
    };

    const currentBowler = currentInnings.bowlers[0] || {
      id: 'bw1',
      name: 'Bowler',
      overs: 0,
      maidens: 0,
      runs: 0,
      wickets: 0,
      economy: 0,
      wides: 0,
      noBalls: 0,
      dots: 0,
    };

    return {
      match,
      currentInnings,
      innings,
      currentBatters: [b1, b2],
      currentBowler,
      currentPartnership: {
        runs: b1.runs + b2.runs,
        balls: b1.balls + b2.balls,
        batter1Id: b1.id,
        batter1Name: b1.name,
        batter1Runs: b1.runs,
        batter1Balls: b1.balls,
        batter2Id: b2.id,
        batter2Name: b2.name,
        batter2Runs: b2.runs,
        batter2Balls: b2.balls,
      },
      thisOver: [],
      lastOvers: [],
      recentBalls: [],
      analytics: {
        currentRunRate: currentInnings.runRate,
        dotBallPercentage: 40,
        boundaryPercentage: 15,
        winProbability: {
          teamAId: match.teamA.id,
          teamAName: match.teamA.name,
          teamAProb: 50,
          teamBId: match.teamB.id,
          teamBName: match.teamB.name,
          teamBProb: 50,
          confidence: 70,
        },
      },
      sequence: 1,
      stateHash: `${match.id}-${currentInnings.runs}-${currentInnings.wickets}-${currentInnings.overs}`,
      lastUpdated: Date.now(),
    };
  }
}
